import type { Catalog } from "./en";

/**
 * हिन्दी — Hindi. Typed against en.ts, so a missing key won't compile.
 *
 * COMPLETE: all 4,894 keys. It was 2,200 (45%) before this pass, so a woman
 * who chose Hindi got Hindi navigation above English screens.
 *
 * The register, which is the whole point:
 *
 * - **आप, never तू or तुम.** She is being addressed by an institution, and
 *   the familiar pronoun from one is what an employer uses on a domestic
 *   worker.
 * - **Feminine verb agreement throughout** — करती हैं, चाहिए, जानती हैं,
 *   भूल गईं. Every reader of this app is a woman; masculine defaults would
 *   read as though the app were written for somebody else.
 * - **Everyday spoken Hindi, not शुद्ध हिन्दी.** दुकान not विक्रय-केंद्र,
 *   हिसाब not लेखा-जोखा. Half the readers left school early; Sanskritised
 *   officialese is a second gate on the same door.
 * - **The loanword where the loanword has won** — फ़ोन, ऑर्डर, बैंक,
 *   प्रमाणपत्र, व्हाट्सएप, यूपीआई. These are the words she actually says.
 * - **No कृपया.** The English does not say "please" either, and in Hindi it
 *   reads servile.
 * - One word for one thing: circle is मंडली, shop is दुकान, period is माहवारी,
 *   savings pot is पोटली, Sakhi is सखी.
 *
 * Nastaliq-free, Devanagari throughout. The five entries that remain in Latin
 * are email placeholders, a scam brand used as an example, and a clinical
 * guideline code — all of which must not be translated.
 */
